     1→// ============================================================================
     2→// FreeLang Executor 모듈 - 물리 계획 실행 엔진
     3→// ============================================================================
     4→// 목표: PhysicalPlan 연산자를 순회 실행하여 결과 집합 생성
     5→// 원리:
     6→//   1. RowBuffer: 행 인덱스 배열로 추적 (메모리 효율)
     7→//   2. Executor: 계획 + 행 버퍼 + 결과 집합 + 컨텍스트
     8→//   3. 메인 루프: root_op_idx부터 시작 → 연산자별 실행 → next_op 순회
     9→//   4. 연산자 유형: TABLE_SCAN, FILTER, SORT, LIMIT, AGGREGATE
    10→// 구조:
    11→//   - 상수 정의 (에러 코드 130-133, 제한값)
    12→//   - RowBuffer, Executor 구조체
    13→//   - 초기화 및 실행 함수 (12개 공개 API)
    14→//   - 연산자별 헬퍼 함수
    15→// ============================================================================
    16→
    17→module executor {
    18→    // === 에러 코드 ===
    19→    const EXEC_OK:               i32 = 0;
    20→    const EXEC_ERR_NOT_FOUND:    i32 = 130;
    21→    const EXEC_ERR_INVALID_OP:   i32 = 131;
    22→    const EXEC_ERR_INVALID_PLAN: i32 = 132;
    23→    const EXEC_ERR_FULL:         i32 = 133;
    24→
    25→    // === 제한값 ===
    26→    const MAX_ROW_BUFFER: i32 = 1024;
    27→
    28→    // === 데이터 구조체 ===
    29→
    30→    // 행 버퍼 (행 인덱스 배열)
    31→    struct RowBuffer {
    32→        row_indices: [i32];
    33→        count:       i32;
    34→    }
    35→
    36→    // 실행 엔진
    37→    struct Executor {
    38→        plan:       physical_plan.PhysicalPlan;
    39→        row_buf:    RowBuffer;
    40→        result:     result_set.ResultSet;
    41→        qctx:       query_context.QueryContext;
    42→        has_error:  bool;
    43→        error_code: i32;
    44→    }
    45→
    46→    // === 초기화 함수 ===
    47→
    48→    // 새로운 Executor 생성 및 초기화
    49→    func executor_new() -> Executor {
    50→        let ex = Executor{
    51→            plan:       physical_plan.physical_plan_new(),
    52→            row_buf:    RowBuffer{
    53→                row_indices: make([i32], MAX_ROW_BUFFER),
    54→                count:       0,
    55→            },
    56→            result:     result_set.result_set_new(16),
    57→            qctx:       query_context.query_context_new(0),
    58→            has_error:  false,
    59→            error_code: EXEC_OK,
    60→        };
    61→        return ex;
    62→    }
    63→
    64→    // Executor 초기화 (계획 및 테이블 설정)
    65→    func executor_init(ex: *Executor, pp: physical_plan.PhysicalPlan, t: schema.Table) -> i32 {
    66→        // 물리 계획 검증
    67→        if !physical_plan.physical_plan_validate(&pp) {
    68→            ex.has_error = true;
    69→            ex.error_code = EXEC_ERR_INVALID_PLAN;
    70→            return EXEC_ERR_INVALID_PLAN;
    71→        }
    72→
    73→        // 계획 설정
    74→        ex.plan = pp;
    75→
    76→        // 행 버퍼 초기화
    77→        ex.row_buf.count = 0;
    78→
    79→        // 결과 집합 초기화
    80→        let col_count = t.schema.col_count;
    81→        ex.result = result_set.result_set_new(col_count);
    82→
    83→        // 컨텍스트 초기화
    84→        ex.qctx = query_context.query_context_new(1);
    85→
    86→        ex.has_error = false;
    87→        ex.error_code = EXEC_OK;
    88→
    89→        return EXEC_OK;
    90→    }
    91→
    92→    // === 메인 실행 루프 ===
    93→
    94→    // 물리 계획 실행 (메인 엔진)
    95→    func executor_execute(ex: *Executor, t: schema.Table) -> i32 {
    96→        // 계획 검증
    97→        if ex.plan.root_op_idx < 0 {
    98→            ex.has_error = true;
    99→            ex.error_code = EXEC_ERR_INVALID_PLAN;
   100→            return EXEC_ERR_INVALID_PLAN;
   101→        }
   102→
   103→        // 행 버퍼 초기화
   104→        ex.row_buf.count = 0;
   105→
   106→        // 결과 집합 초기화
   107→        let res = ex.result.result_set_clear();
   108→        if res != result_set.RESULT_OK {
   109→            ex.has_error = true;
   110→            ex.error_code = EXEC_ERR_FULL;
   111→            return EXEC_ERR_FULL;
   112→        }
   113→
   114→        // 루트 연산자부터 시작
   115→        let op_idx = ex.plan.root_op_idx;
   116→        let visited = 0;
   117→
   118→        // 파이프라인 순회 (최대 32개 연산자)
   119→        for visited = 0; visited < 32 && op_idx >= 0; visited = visited + 1 {
   120→            if op_idx >= physical_plan.MAX_OPS {
   121→                ex.has_error = true;
   122→                ex.error_code = EXEC_ERR_INVALID_OP;
   123→                return EXEC_ERR_INVALID_OP;
   124→            }
   125→
   126→            let op = ex.plan.ops[op_idx];
   127→
   128→            // 연산자 타입별 실행
   129→            if op.op_type == physical_plan.PHYS_PLAN_TABLE_SCAN {
   130→                let err = executor_exec_table_scan(ex, t);
   131→                if err != EXEC_OK {
   132→                    ex.has_error = true;
   133→                    ex.error_code = err;
   134→                    return err;
   135→                }
   136→            } else if op.op_type == physical_plan.PHYS_PLAN_FILTER {
   137→                let err = executor_exec_filter(ex, t, op.col_idx);
   138→                if err != EXEC_OK {
   139→                    ex.has_error = true;
   140→                    ex.error_code = err;
   141→                    return err;
   142→                }
   143→            } else if op.op_type == physical_plan.PHYS_PLAN_SORT {
   144→                let err = executor_exec_sort(ex, t, op.col_idx);
   145→                if err != EXEC_OK {
   146→                    ex.has_error = true;
   147→                    ex.error_code = err;
   148→                    return err;
   149→                }
   150→            } else if op.op_type == physical_plan.PHYS_PLAN_LIMIT {
   151→                let err = executor_exec_limit(ex, op.limit_count);
   152→                if err != EXEC_OK {
   153→                    ex.has_error = true;
   154→                    ex.error_code = err;
   155→                    return err;
   156→                }
   157→            } else if op.op_type == physical_plan.PHYS_PLAN_AGGREGATE {
   158→                let err = executor_exec_aggregate(ex, t, op.agg_type, op.col_idx);
   159→                if err != EXEC_OK {
   160→                    ex.has_error = true;
   161→                    ex.error_code = err;
   162→                    return err;
   163→                }
   164→            }
   165→
   166→            // 다음 연산자로 이동
   167→            op_idx = op.next_op;
   168→        }
   169→
   170→        // 행 버퍼 → 결과 집합 복사
   171→        let err = executor_finalize_result(ex, t);
   172→        if err != EXEC_OK {
   173→            ex.has_error = true;
   174→            ex.error_code = err;
   175→            return err;
   176→        }
   177→
   178→        ex.has_error = false;
   179→        ex.error_code = EXEC_OK;
   180→        return EXEC_OK;
   181→    }
   182→
   183→    // === 연산자 실행 함수 ===
   184→
   185→    // TABLE_SCAN: 모든 활성 행을 행 버퍼에 추가
   186→    func executor_exec_table_scan(ex: *Executor, t: schema.Table) -> i32 {
   187→        let row_idx = 0;
   188→
   189→        // 모든 행 순회
   190→        for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
   191→            // 소프트 삭제 확인
   192→            if !t.deleted_flags[row_idx] {
   193→                // 행 버퍼 용량 확인
   194→                if ex.row_buf.count >= MAX_ROW_BUFFER {
   195→                    return EXEC_ERR_FULL;
   196→                }
   197→
   198→                // 행 인덱스 추가
   199→                ex.row_buf.row_indices[ex.row_buf.count] = row_idx;
   200→                ex.row_buf.count = ex.row_buf.count + 1;
   201→            }
   202→        }
   203→
   204→        return EXEC_OK;
   205→    }
   206→
   207→    // FILTER: 조건(col_idx > 0)을 만족하는 행만 유지
   208→    func executor_exec_filter(ex: *Executor, t: schema.Table, col_idx: i32) -> i32 {
   209→        if col_idx < 0 || col_idx >= t.schema.col_count {
   210→            return EXEC_ERR_INVALID_OP;
   211→        }
   212→
   213→        let new_count = 0;
   214→        let i = 0;
   215→
   216→        // 각 행에 대해 필터 조건 적용
   217→        for i = 0; i < ex.row_buf.count; i = i + 1 {
   218→            let row_idx = ex.row_buf.row_indices[i];
   219→
   220→            // 컬럼 값 추출 (정수 컬럼으로 가정)
   221→            let col_val = t.int_cols[col_idx * schema.MAX_ROWS + row_idx];
   222→
   223→            // > 0 조건 필터
   224→            if col_val > 0 {
   225→                ex.row_buf.row_indices[new_count] = row_idx;
   226→                new_count = new_count + 1;
   227→            }
   228→        }
   229→
   230→        ex.row_buf.count = new_count;
   231→        return EXEC_OK;
   232→    }
   233→
   234→    // SORT: 삽입 정렬(insertion sort)로 행 정렬
   235→    func executor_exec_sort(ex: *Executor, t: schema.Table, sort_col: i32) -> i32 {
   236→        if sort_col < 0 || sort_col >= t.schema.col_count {
   237→            return EXEC_ERR_INVALID_OP;
   238→        }
   239→
   240→        let i = 1;
   241→
   242→        // 삽입 정렬
   243→        for i = 1; i < ex.row_buf.count; i = i + 1 {
   244→            let key_idx = ex.row_buf.row_indices[i];
   245→            let key_val = t.int_cols[sort_col * schema.MAX_ROWS + key_idx];
   246→
   247→            let j = i - 1;
   248→
   249→            // 삽입 위치 찾기
   250→            for j = i - 1; j >= 0; j = j - 1 {
   251→                let curr_row_idx = ex.row_buf.row_indices[j];
   252→                let curr_val = t.int_cols[sort_col * schema.MAX_ROWS + curr_row_idx];
   253→
   254→                if curr_val <= key_val {
   255→                    break;
   256→                }
   257→
   258→                // 한 칸씩 뒤로 이동
   259→                ex.row_buf.row_indices[j + 1] = ex.row_buf.row_indices[j];
   260→            }
   261→
   262→            // 올바른 위치에 삽입
   263→            ex.row_buf.row_indices[j + 1] = key_idx;
   264→        }
   265→
   266→        return EXEC_OK;
   267→    }
   268→
   269→    // LIMIT: 행 개수 제한
   270→    func executor_exec_limit(ex: *Executor, limit_count: i32) -> i32 {
   271→        if limit_count <= 0 {
   272→            return EXEC_OK;
   273→        }
   274→
   275→        if ex.row_buf.count > limit_count {
   276→            ex.row_buf.count = limit_count;
   277→        }
   278→
   279→        return EXEC_OK;
   280→    }
   281→
   282→    // AGGREGATE: 집계 함수 실행 (COUNT/SUM/MAX/MIN)
   283→    func executor_exec_aggregate(ex: *Executor, t: schema.Table, agg_type: i32, agg_col: i32) -> i32 {
   284→        if agg_col < 0 || agg_col >= t.schema.col_count {
   285→            return EXEC_ERR_INVALID_OP;
   286→        }
   287→
   288→        let agg_val: i64 = 0;
   289→        let i = 0;
   290→
   291→        if agg_type == physical_plan.PHYS_AGG_COUNT {
   292→            agg_val = i64(ex.row_buf.count);
   293→        } else if agg_type == physical_plan.PHYS_AGG_SUM {
   294→            agg_val = 0;
   295→            for i = 0; i < ex.row_buf.count; i = i + 1 {
   296→                let row_idx = ex.row_buf.row_indices[i];
   297→                let col_val = t.int_cols[agg_col * schema.MAX_ROWS + row_idx];
   298→                agg_val = agg_val + col_val;
   299→            }
   300→        } else if agg_type == physical_plan.PHYS_AGG_MAX {
   301→            agg_val = -9223372036854775808;
   302→            for i = 0; i < ex.row_buf.count; i = i + 1 {
   303→                let row_idx = ex.row_buf.row_indices[i];
   304→                let col_val = t.int_cols[agg_col * schema.MAX_ROWS + row_idx];
   305→                if col_val > agg_val {
   306→                    agg_val = col_val;
   307→                }
   308→            }
   309→        } else if agg_type == physical_plan.PHYS_AGG_MIN {
   310→            agg_val = 9223372036854775807;
   311→            for i = 0; i < ex.row_buf.count; i = i + 1 {
   312→                let row_idx = ex.row_buf.row_indices[i];
   313→                let col_val = t.int_cols[agg_col * schema.MAX_ROWS + row_idx];
   314→                if col_val < agg_val {
   315→                    agg_val = col_val;
   316→                }
   317→            }
   318→        }
   319→
   320→        // 결과를 단일 행으로 저장
   321→        ex.row_buf.count = 1;
   322→        ex.row_buf.row_indices[0] = 0;
   323→
   324→        let new_row = result_set.ResultRow{
   325→            int_vals:  make([i64],    result_set.MAX_RESULT_COLS),
   326→            str_vals:  make([string], result_set.MAX_RESULT_COLS),
   327→            bool_vals: make([bool],   result_set.MAX_RESULT_COLS),
   328→            col_count: 1,
   329→        };
   330→
   331→        new_row.int_vals[0] = agg_val;
   332→        ex.result.rows[0] = new_row;
   333→        ex.result.row_count = 1;
   334→
   335→        return EXEC_OK;
   336→    }
   337→
   338→    // === 결과 수집 함수 ===
   339→
   340→    // 행 버퍼를 결과 집합에 복사
   341→    func executor_finalize_result(ex: *Executor, t: schema.Table) -> i32 {
   342→        let i = 0;
   343→
   344→        // 각 행 인덱스를 결과 집합에 추가
   345→        for i = 0; i < ex.row_buf.count; i = i + 1 {
   346→            let row_idx = ex.row_buf.row_indices[i];
   347→
   348→            let err = ex.result.result_set_add_row_from_schema(t, row_idx);
   349→            if err != result_set.RESULT_OK {
   350→                return EXEC_ERR_FULL;
   351→            }
   352→        }
   353→
   354→        return EXEC_OK;
   355→    }
   356→
   357→    // === 조회 함수 ===
   358→
   359→    // 결과 집합 반환
   360→    func executor_get_result(ex: *Executor) -> result_set.ResultSet {
   361→        return ex.result;
   362→    }
   363→
   364→    // 결과 행 개수 반환
   365→    func executor_get_row_count(ex: *Executor) -> i32 {
   366→        return ex.result.row_count;
   367→    }
   368→
   369→    // === 통계 및 디버그 함수 ===
   370→
   371→    // Executor 상태 문자열 반환
   372→    func executor_stats(ex: *Executor) -> string {
   373→        let stat = "Executor {row_buf.count: ";
   374→        stat = stat + i32_to_str(ex.row_buf.count);
   375→        stat = stat + ", result.row_count: ";
   376→        stat = stat + i32_to_str(ex.result.row_count);
   377→        stat = stat + ", error_code: ";
   378→        stat = stat + i32_to_str(ex.error_code);
   379→        stat = stat + "}";
   380→        return stat;
   381→    }
   382→
   383→    // === 헬퍼 함수 ===
   384→
   385→    // i32를 문자열로 변환
   386→    @inline
   387→    func i32_to_str(n: i32) -> string {
   388→        if n == 0 { return "0"; }
   389→        if n == 1 { return "1"; }
   390→        if n == 2 { return "2"; }
   391→        if n == 3 { return "3"; }
   392→        if n == 4 { return "4"; }
   393→        if n == 5 { return "5"; }
   394→        if n == 6 { return "6"; }
   395→        if n == 7 { return "7"; }
   396→        if n == 8 { return "8"; }
   397→        if n == 9 { return "9"; }
   398→        if n < 0 { return "-" + i32_to_str(-n); }
   399→        let d = n / 10;
   400→        let r = n % 10;
   401→        return i32_to_str(d) + i32_to_str(r);
   402→    }
   403→}
