     1→// ============================================================================
     2→// FreeLang Planner 모듈 - 비용 기반 쿼리 실행 계획
     3→// ============================================================================
     4→// 목표: WHERE 절 기반으로 최적의 실행 경로 선택
     5→// 원리:
     6→//   1. 테이블 통계: row_count, 컬럼 min/max
     7→//   2. 비용 추정: 풀스캔 O(n), 인덱스 범위 O(log n + k)
     8→//   3. 계획 선택: 비용이 낮은 경로 선택
     9→// 구조:
    10→//   - TableStats, ExecPlan 구조체
    11→//   - 통계 수집 (stats_build, stats_update)
    12→//   - 계획 생성 (plan_query)
    13→//   - 계획 기반 실행 (execute_planned)
    14→// ============================================================================
    15→
    16→module planner {
    17→    // === 계획 타입 ===
    18→    const PLAN_FULL_SCAN:   i32 = 1;
    19→    const PLAN_INDEX_EQ:    i32 = 2;
    20→    const PLAN_INDEX_RANGE: i32 = 3;
    21→    const PLAN_INDEX_LIKE:  i32 = 4;
    22→
    23→    // === 제한값 ===
    24→    const MAX_COLS: i32 = 16;
    25→    const MAX_ROWS: i32 = 1024;
    26→
    27→    // === 에러 코드 ===
    28→    const PLAN_OK:           i32 = 0;
    29→    const PLAN_ERR_NO_STATS: i32 = 60;
    30→
    31→    // === 데이터 구조체 ===
    32→
    33→    // 테이블 통계 (통계 기반 비용 추정용)
    34→    struct TableStats {
    35→        row_count:    i32;
    36→        col_count:    i32;
    37→        col_min:      [i64];   // 각 컬럼별 MIN (INT만)
    38→        col_max:      [i64];   // 각 컬럼별 MAX (INT만)
    39→        col_null_cnt: [i32];   // NULL 수
    40→        col_type:     [i32];   // 컬럼 타입 (INT/STR/BOOL)
    41→    }
    42→
    43→    // 실행 계획
    44→    struct ExecPlan {
    45→        plan_type:  i32;   // PLAN_* 상수
    46→        index_col:  i32;   // 사용할 인덱스 컬럼 (-1 = 없음)
    47→        est_rows:   i32;   // 예상 결과 행 수
    48→        cost:       i32;   // 비용 추정치 (낮을수록 좋음)
    49→        error_code: i32;   // 에러 코드
    50→    }
    51→
    52→    // === 통계 생성 ===
    53→
    54→    // 테이블에서 통계 수집 (스캔 기반)
    55→    func stats_build(t: schema.Table) -> TableStats {
    56→        let stats = TableStats{
    57→            row_count:    t.row_count,
    58→            col_count:    t.schema.col_count,
    59→            col_min:      make([i64], MAX_COLS),
    60→            col_max:      make([i64], MAX_COLS),
    61→            col_null_cnt: make([i32], MAX_COLS),
    62→            col_type:     make([i32], MAX_COLS),
    63→        };
    64→
    65→        // 각 컬럼 타입 저장
    66→        let col_idx = 0;
    67→        for col_idx = 0; col_idx < stats.col_count; col_idx = col_idx + 1 {
    68→            stats.col_type[col_idx] = t.schema.col_defs[col_idx].col_type;
    69→        }
    70→
    71→        // INT 컬럼만 MIN/MAX 계산
    72→        for col_idx = 0; col_idx < stats.col_count; col_idx = col_idx + 1 {
    73→            if t.schema.col_defs[col_idx].col_type != schema.COL_TYPE_INT {
    74→                continue;
    75→            }
    76→
    77→            let found_first = false;
    78→            let row_idx = 0;
    79→            for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
    80→                if t.deleted_flags[row_idx] {
    81→                    stats.col_null_cnt[col_idx] = stats.col_null_cnt[col_idx] + 1;
    82→                    continue;
    83→                }
    84→
    85→                // SoA 레이아웃에서 값 읽기: [col_idx * MAX_ROWS + row_idx]
    86→                let soa_idx = col_idx * MAX_ROWS + row_idx;
    87→                let val = t.int_cols[soa_idx];
    88→
    89→                if !found_first {
    90→                    stats.col_min[col_idx] = val;
    91→                    stats.col_max[col_idx] = val;
    92→                    found_first = true;
    93→                } else {
    94→                    if val < stats.col_min[col_idx] {
    95→                        stats.col_min[col_idx] = val;
    96→                    }
    97→                    if val > stats.col_max[col_idx] {
    98→                        stats.col_max[col_idx] = val;
    99→                    }
   100→                }
   101→            }
   102→        }
   103→
   104→        return stats;
   105→    }
