   185→    // === 비용 추정 헬퍼 함수 ===
   186→
   187→    // log2(n) 근사 (비트 길이 이용)
   188→    @inline
   189→    func log_cost(n: i32) -> i32 {
   190→        if n <= 1 { return 0; }
   191→        if n <= 2 { return 1; }
   192→        if n <= 4 { return 2; }
   193→        if n <= 8 { return 3; }
   194→        if n <= 16 { return 4; }
   195→        if n <= 32 { return 5; }
   196→        if n <= 64 { return 6; }
   197→        if n <= 128 { return 7; }
   198→        if n <= 256 { return 8; }
   199→        if n <= 512 { return 9; }
   200→        if n <= 1024 { return 10; }
   201→        return 11;
   202→    }
