   266→    // 계획에 따라 인덱스 또는 풀스캔 사용
   267→    func execute_planned(t: schema.Table, q: query.Query,
   268→                        plan: ExecPlan, idx: index.BTreeIndex) -> query.QueryResult {
   269→
   270→        // PLAN_FULL_SCAN: 기존 query_execute 사용 (풀스캔)
   271→        if plan.plan_type == PLAN_FULL_SCAN {
   272→            return query.execute(t, q);
   273→        }
   274→
   275→        // PLAN_INDEX_EQ: 정확한 인덱스 탐색
   276→        if plan.plan_type == PLAN_INDEX_EQ {
   277→            let result = query.QueryResult{
   278→                row_indices: make([i32], 1024),
   279→                row_count:   0,
   280→                agg_value:   0,
   281→                error_code:  query.QUERY_OK,
   282→            };
   283→
   284→            let search_val = q.wheres[0].int_val;
   285→            let found_row_id, found = idx.index_search(search_val);
   286→
   287→            // 인덱스에서 찾은 row_id를 테이블 행 인덱스로 변환
   288→            if found {
   289→                let row_idx = 0;
   290→                for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
   291→                    if t.row_ids[row_idx] == found_row_id && !t.deleted_flags[row_idx] {
   292→                        result.row_indices[0] = row_idx;
   293→                        result.row_count = 1;
   294→                        break;
   295→                    }
   296→                }
   297→            }
   298→
   299→            return result;
   300→        }
   301→
   302→        // PLAN_INDEX_RANGE: 범위 탐색
   303→        if plan.plan_type == PLAN_INDEX_RANGE {
   304→            let result = query.QueryResult{
   305→                row_indices: make([i32], 1024),
   306→                row_count:   0,
   307→                agg_value:   0,
   308→                error_code:  query.QUERY_OK,
   309→            };
   310→
   311→            let min_val = q.wheres[0].int_val;
   312→            let op = q.wheres[0].op;
   313→            let max_val = min_val + 100;  // 범위 크기 (간단화)
   314→
   315→            // 범위 탐색: min_val ~ max_val 범위의 row_id 반환
   316→            // (index_range 함수는 index.fl에 구현되어 있다고 가정)
   317→            let i = 0;
   318→            for i = 0; i < t.row_count && result.row_count < 1024; i = i + 1 {
   319→                if t.deleted_flags[i] {
   320→                    continue;
   321→                }
   322→
   323→                let soa_idx = plan.index_col * MAX_ROWS + i;
   324→                let val = t.int_cols[soa_idx];
   325→
   326→                let matches = false;
   327→                if op == query.OP_GT {
   328→                    matches = val > min_val;
   329→                } else if op == query.OP_LT {
   330→                    matches = val < min_val;
   331→                } else if op == query.OP_GE {
   332→                    matches = val >= min_val;
   333→                } else if op == query.OP_LE {
   334→                    matches = val <= min_val;
   335→                }
   336→
   337→                if matches {
   338→                    result.row_indices[result.row_count] = i;
   339→                    result.row_count = result.row_count + 1;
   340→                }
   341→            }
   342→
   343→            return result;
   344→        }
   345→
   346→        // PLAN_INDEX_LIKE: 문자열 접두어 탐색
   347→        if plan.plan_type == PLAN_INDEX_LIKE {
   348→            let result = query.QueryResult{
   349→                row_indices: make([i32], 1024),
   350→                row_count:   0,
   351→                agg_value:   0,
   352→                error_code:  query.QUERY_OK,
   353→            };
   354→
   355→            // 문자열 인덱스 사용 (아직 미구현, 풀스캔 대신)
   356→            // 여기서는 간단화하여 풀스캔 로직 사용
   357→            let prefix = q.wheres[0].str_val;
   358→            let i = 0;
   359→            for i = 0; i < t.row_count && result.row_count < 1024; i = i + 1 {
   360→                if t.deleted_flags[i] {
   361→                    continue;
   362→                }
   363→
   364→                let soa_idx = plan.index_col * MAX_ROWS + i;
   365→                let str_val = t.str_cols[soa_idx];
   366→
   367→                // 접두어 매칭 (간단 구현)
   368→                if str_prefix_match(str_val, prefix) {
   369→                    result.row_indices[result.row_count] = i;
   370→                    result.row_count = result.row_count + 1;
   371→                }
   372→            }
   373→
   374→            return result;
   375→        }
   376→
   377→        // 기본: 풀스캔
   378→        return query.execute(t, q);
   379→    }
